import { ref, unref } from 'vue';
import { useStore } from 'vuex';
import { useAlert } from 'dashboard/composables';
import { useI18n } from 'vue-i18n';
import { CLOSED_PICKUP_LABEL } from 'dashboard/helper/rottaPickup';
import { useMapGetter } from 'dashboard/composables/store.js';
import { useConversationRequiredAttributes } from 'dashboard/composables/useConversationRequiredAttributes';
import ConversationAPI from 'dashboard/api/conversations';
import {
  beginConversationLabelMutation,
  isConversationLabelMutationCurrent,
  isLatestConversationLabelMutation,
  withConversationLabelMutationLock,
} from 'dashboard/helper/conversationLabelMutationQueue';
import { emitter } from 'shared/helpers/mitt';
import wootConstants from 'dashboard/constants/globals';

const ARCHIVED_LABEL_KEYS = new Set(['arquivado', 'arquivados']);

const normalizedLabelKey = label =>
  String(label || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/^\[\d+\]\s*/, '')
    .replace(/^\d+[-\s]+/, '')
    .replace(/\s+/g, '-');

const isArchivedLabel = label =>
  ARCHIVED_LABEL_KEYS.has(normalizedLabelKey(label));

export const mergeConversationLabels = (
  conversation,
  { add = [], remove = [] } = {}
) => {
  const currentLabels = Array.isArray(conversation?.labels)
    ? conversation.labels.map(label =>
        typeof label === 'string' ? label : label?.title
      )
    : [];
  const labelsToAdd = Array.isArray(add) ? add : [add];
  const labelsToRemove = new Set(Array.isArray(remove) ? remove : [remove]);
  const archivedLabel = labelsToAdd.find(isArchivedLabel);

  if (archivedLabel) return [archivedLabel];

  return [
    ...new Set([...currentLabels, ...labelsToAdd].filter(Boolean)),
  ].filter(label => !labelsToRemove.has(label));
};

export function useBulkActions() {
  const store = useStore();
  const { t } = useI18n();
  const { checkMissingAttributes } = useConversationRequiredAttributes();

  const selectedConversations = useMapGetter(
    'bulkActions/getSelectedConversationIds'
  );
  const selectedInboxes = ref([]);

  function selectConversation(conversationId, inboxId) {
    store.dispatch('bulkActions/setSelectedConversationIds', conversationId);
    selectedInboxes.value = [...selectedInboxes.value, inboxId];
  }

  function deSelectConversation(conversationId, inboxId) {
    store.dispatch('bulkActions/removeSelectedConversationIds', conversationId);
    // Only remove one instance of the inboxId, not all
    // This handles the case where multiple conversations from the same inbox are selected
    const index = selectedInboxes.value.indexOf(inboxId);
    if (index > -1) {
      selectedInboxes.value = [
        ...selectedInboxes.value.slice(0, index),
        ...selectedInboxes.value.slice(index + 1),
      ];
    }
  }

  function resetBulkActions() {
    store.dispatch('bulkActions/clearSelectedConversationIds');
    selectedInboxes.value = [];
  }

  function selectAllConversations(check, conversationList) {
    const availableConversations = unref(conversationList);
    if (check) {
      store.dispatch(
        'bulkActions/setSelectedConversationIds',
        availableConversations.map(item => item.id)
      );
      selectedInboxes.value = availableConversations.map(item => item.inbox_id);
    } else {
      resetBulkActions();
    }
  }

  function isConversationSelected(id) {
    return selectedConversations.value.includes(id);
  }

  const getConversationLabels = conversation =>
    Array.isArray(conversation?.labels)
      ? conversation.labels
          .map(label => (typeof label === 'string' ? label : label?.title))
          .filter(Boolean)
      : [];

  const prepareConversationLabelChanges = (ids, change) => {
    const previous = new Map();
    const next = new Map();
    ids.forEach(id => {
      const conversation = store.getters.getConversationById(id);
      if (!conversation) return;
      previous.set(String(id), getConversationLabels(conversation));
      next.set(String(id), mergeConversationLabels(conversation, change));
    });
    return { previous, next };
  };

  async function updateConversationLabelsLocally(labelsById, versions) {
    await Promise.all(
      [...labelsById.entries()].map(async ([id, labels]) => {
        if (!isLatestConversationLabelMutation(id, versions)) return;
        const conversation = store.getters.getConversationById(Number(id));
        if (!conversation) return;
        await store.dispatch('updateConversation', { ...conversation, labels });
      })
    );
  }

  async function reconcileConversationLabels(ids, fallback, versions) {
    await Promise.all(
      ids.map(async id => {
        if (!isLatestConversationLabelMutation(id, versions)) return;
        let labels = fallback.get(String(id)) || [];
        try {
          const response = await ConversationAPI.getLabels(id);
          const payload = response.data.payload;
          if (Array.isArray(payload)) {
            labels = payload
              .map(label => (typeof label === 'string' ? label : label?.title))
              .filter(Boolean);
          } else if (Array.isArray(payload?.labels)) {
            labels = payload.labels
              .map(label => (typeof label === 'string' ? label : label?.title))
              .filter(Boolean);
          }
        } catch {
          // Preserve the last known labels if the reconciliation request also fails.
        }
        const conversation = store.getters.getConversationById(Number(id));
        if (conversation && isLatestConversationLabelMutation(id, versions)) {
          await store.dispatch('updateConversation', {
            ...conversation,
            labels,
          });
        }
      })
    );
  }

  // Same method used in context menu, conversationId being passed from there.
  async function onAssignAgent(agent, conversationId = null) {
    try {
      await store.dispatch('bulkActions/process', {
        type: 'Conversation',
        ids: conversationId || selectedConversations.value,
        fields: {
          assignee_id: agent.id,
        },
      });
      store.dispatch('bulkActions/clearSelectedConversationIds');
      if (conversationId) {
        useAlert(
          t('CONVERSATION.CARD_CONTEXT_MENU.API.AGENT_ASSIGNMENT.SUCCESFUL', {
            agentName: agent.name,
            conversationId,
          })
        );
      } else {
        useAlert(t('BULK_ACTION.ASSIGN_SUCCESFUL'));
      }
    } catch (err) {
      useAlert(t('BULK_ACTION.ASSIGN_FAILED'));
    }
  }

  // Same method used in context menu, conversationId being passed from there.
  async function onAssignLabels(newLabels, conversationId = null) {
    const labelsToAssign = Array.isArray(newLabels) ? newLabels : [newLabels];
    if (!conversationId && labelsToAssign.includes(CLOSED_PICKUP_LABEL)) {
      const ids = [...selectedConversations.value];
      // Each conversation requires its own confirmed pickup date.
      const completed = await ids.reduce(
        async (previous, id) =>
          (await previous) && onAssignLabels(labelsToAssign, id),
        Promise.resolve(true)
      );
      if (!completed) return false;
      store.dispatch('bulkActions/clearSelectedConversationIds');
      return true;
    }
    if (conversationId) {
      try {
        const updated = await store.dispatch('conversationLabels/mutate', {
          conversationId,
          add: labelsToAssign,
        });
        if (updated?.status === 'superseded') return true;
        if (updated?.status === 'cancelled') return false;
        if (updated?.status !== 'success' && updated !== true) {
          throw new Error('Conversation labels were not updated');
        }
        await store.dispatch('labels/get', { forceNetwork: true });
        if (
          updated?.version != null &&
          !isConversationLabelMutationCurrent(conversationId, updated.version)
        ) {
          return true;
        }
        emitter.emit('fetch_conversation_stats');
        useAlert(
          t('CONVERSATION.CARD_CONTEXT_MENU.API.LABEL_ASSIGNMENT.SUCCESFUL', {
            labelName: labelsToAssign[0],
            conversationId,
          }),
          labelsToAssign.some(isArchivedLabel) ? { variant: 'danger' } : null
        );
        return true;
      } catch (err) {
        useAlert(t('BULK_ACTION.LABELS.ASSIGN_FAILED'));
        return false;
      }
    }

    const conversationIds = conversationId
      ? [conversationId]
      : [...selectedConversations.value];
    const versions = beginConversationLabelMutation(conversationIds);
    const { previous, next } = prepareConversationLabelChanges(
      conversationIds,
      { add: labelsToAssign }
    );
    await updateConversationLabelsLocally(next, versions);
    try {
      await withConversationLabelMutationLock(conversationIds, async () => {
        await store.dispatch('bulkActions/process', {
          type: 'Conversation',
          ids: conversationIds,
          labels: { add: labelsToAssign },
        });
        if (conversationIds.length === 1) {
          await reconcileConversationLabels(conversationIds, next, versions);
        } else {
          await updateConversationLabelsLocally(next, versions);
        }
      });
      await store.dispatch('labels/get', { forceNetwork: true });
      emitter.emit('fetch_conversation_stats');
      store.dispatch('bulkActions/clearSelectedConversationIds');
      if (conversationId) {
        useAlert(
          t('CONVERSATION.CARD_CONTEXT_MENU.API.LABEL_ASSIGNMENT.SUCCESFUL', {
            labelName: labelsToAssign[0],
            conversationId,
          }),
          labelsToAssign.some(isArchivedLabel) ? { variant: 'danger' } : null
        );
      } else {
        useAlert(
          t('BULK_ACTION.LABELS.ASSIGN_SUCCESFUL'),
          labelsToAssign.some(isArchivedLabel) ? { variant: 'danger' } : null
        );
      }
      return true;
    } catch (err) {
      await reconcileConversationLabels(conversationIds, previous, versions);
      useAlert(t('BULK_ACTION.LABELS.ASSIGN_FAILED'));
      return false;
    }
  }

  // Used by both context menu and bulk action bar.
  async function onRemoveLabels(labelsToRemove, conversationId = null) {
    if (conversationId) {
      try {
        const updated = await store.dispatch('conversationLabels/mutate', {
          conversationId,
          remove: labelsToRemove,
        });
        if (updated?.status === 'superseded') return true;
        if (updated?.status !== 'success' && updated !== true) {
          throw new Error('Conversation labels were not updated');
        }
        await store.dispatch('labels/get', { forceNetwork: true });
        if (
          updated?.version != null &&
          !isConversationLabelMutationCurrent(conversationId, updated.version)
        ) {
          return true;
        }
        emitter.emit('fetch_conversation_stats');
        useAlert(
          t('CONVERSATION.CARD_CONTEXT_MENU.API.LABEL_REMOVAL.SUCCESFUL', {
            labelName: labelsToRemove[0],
            conversationId,
          })
        );
        return true;
      } catch (err) {
        useAlert(t('CONVERSATION.CARD_CONTEXT_MENU.API.LABEL_REMOVAL.FAILED'));
        return false;
      }
    }

    const conversationIds = conversationId
      ? [conversationId]
      : [...selectedConversations.value];
    const versions = beginConversationLabelMutation(conversationIds);
    const { previous, next } = prepareConversationLabelChanges(
      conversationIds,
      { remove: labelsToRemove }
    );
    await updateConversationLabelsLocally(next, versions);
    try {
      await withConversationLabelMutationLock(conversationIds, async () => {
        await store.dispatch('bulkActions/process', {
          type: 'Conversation',
          ids: conversationIds,
          labels: { remove: labelsToRemove },
        });
        if (conversationIds.length === 1) {
          await reconcileConversationLabels(conversationIds, next, versions);
        } else {
          await updateConversationLabelsLocally(next, versions);
        }
      });
      await store.dispatch('labels/get', { forceNetwork: true });
      emitter.emit('fetch_conversation_stats');

      // Context-menu remove should not disturb an existing bulk selection.
      if (conversationId) {
        useAlert(
          t('CONVERSATION.CARD_CONTEXT_MENU.API.LABEL_REMOVAL.SUCCESFUL', {
            labelName: labelsToRemove[0],
            conversationId,
          })
        );
      } else {
        store.dispatch('bulkActions/clearSelectedConversationIds');
        useAlert(t('BULK_ACTION.LABELS.REMOVE_SUCCESFUL'));
      }
      return true;
    } catch (err) {
      await reconcileConversationLabels(conversationIds, previous, versions);
      useAlert(
        conversationId
          ? t('CONVERSATION.CARD_CONTEXT_MENU.API.LABEL_REMOVAL.FAILED')
          : t('BULK_ACTION.LABELS.REMOVE_FAILED')
      );
      return false;
    }
  }

  async function onAssignTeamsForBulk(team) {
    try {
      await store.dispatch('bulkActions/process', {
        type: 'Conversation',
        ids: selectedConversations.value,
        fields: {
          team_id: team.id,
        },
      });
      store.dispatch('bulkActions/clearSelectedConversationIds');
      useAlert(t('BULK_ACTION.TEAMS.ASSIGN_SUCCESFUL'));
    } catch (err) {
      useAlert(t('BULK_ACTION.TEAMS.ASSIGN_FAILED'));
    }
  }

  async function onUpdateConversations(status, snoozedUntil) {
    if (selectedConversations.value.length === 0) return;

    let conversationIds = selectedConversations.value;
    let skippedCount = 0;

    // If resolving, check for required attributes
    if (status === wootConstants.STATUS_TYPE.RESOLVED) {
      const { validIds, skippedIds } = selectedConversations.value.reduce(
        (acc, id) => {
          const conversation = store.getters.getConversationById(id);
          const currentCustomAttributes = conversation?.custom_attributes || {};
          const { hasMissing } = checkMissingAttributes(
            currentCustomAttributes
          );

          if (!hasMissing) {
            acc.validIds.push(id);
          } else {
            acc.skippedIds.push(id);
          }
          return acc;
        },
        { validIds: [], skippedIds: [] }
      );

      conversationIds = validIds;
      skippedCount = skippedIds.length;

      if (skippedCount > 0 && validIds.length === 0) {
        // All conversations have missing attributes
        useAlert(
          t('BULK_ACTION.RESOLVE.ALL_MISSING_ATTRIBUTES') ||
            'Cannot resolve conversations due to missing required attributes'
        );
        return;
      }
    }

    try {
      if (conversationIds.length > 0) {
        await store.dispatch('bulkActions/process', {
          type: 'Conversation',
          ids: conversationIds,
          fields: {
            status,
          },
          snoozed_until: snoozedUntil,
        });
      }

      store.dispatch('bulkActions/clearSelectedConversationIds');

      if (skippedCount > 0) {
        useAlert(t('BULK_ACTION.RESOLVE.PARTIAL_SUCCESS'));
      } else {
        useAlert(t('BULK_ACTION.UPDATE.UPDATE_SUCCESFUL'));
      }
    } catch (err) {
      useAlert(t('BULK_ACTION.UPDATE.UPDATE_FAILED'));
    }
  }

  return {
    selectedConversations,
    selectedInboxes,
    selectConversation,
    deSelectConversation,
    selectAllConversations,
    resetBulkActions,
    isConversationSelected,
    onAssignAgent,
    onAssignLabels,
    onRemoveLabels,
    onAssignTeamsForBulk,
    onUpdateConversations,
  };
}
