<script setup>
import { computed, ref } from 'vue';
import { useI18n } from 'vue-i18n';
import {
  INPUT_TYPES,
  isPhoneLikeInput,
} from 'dashboard/components-next/taginput/helper/tagInputHelper.js';
import { normalizePhoneSearchQuery } from 'dashboard/components-next/NewConversation/helpers/composeConversationHelper';

import TagInput from 'dashboard/components-next/taginput/TagInput.vue';
import Button from 'dashboard/components-next/button/Button.vue';

const props = defineProps({
  contacts: {
    type: Array,
    required: true,
  },
  selectedContact: {
    type: Object,
    default: null,
  },
  showContactsDropdown: {
    type: Boolean,
    required: true,
  },
  isLoading: {
    type: Boolean,
    required: true,
  },
  isCreatingContact: {
    type: Boolean,
    required: true,
  },
  contactId: {
    type: String,
    default: null,
  },
  contactableInboxesList: {
    type: Array,
    default: () => [],
  },
  showInboxesDropdown: {
    type: Boolean,
    required: true,
  },
  hasErrors: {
    type: Boolean,
    default: false,
  },
});

const emit = defineEmits([
  'searchContacts',
  'setSelectedContact',
  'clearSelectedContact',
  'openConversation',
  'updateDropdown',
]);

const i18nPrefix = 'COMPOSE_NEW_CONVERSATION.FORM.CONTACT_SELECTOR';
const { t } = useI18n();

const inputType = ref(INPUT_TYPES.EMAIL);
const searchValue = ref('');

const normalizePhoneForComparison = value => {
  const digits = String(value || '').replace(/\D/g, '');
  if ([10, 11].includes(digits.length)) return `55${digits}`;
  return digits;
};

const contactsList = computed(() => {
  const contacts = (props.contacts || []).map(contact => {
    const {
      name,
      id,
      thumbnail,
      email,
      phoneNumber: contactPhoneNumber,
      phone_number: contactPhoneNumberSnake,
      ...rest
    } = contact;
    const phoneNumber = contactPhoneNumber || contactPhoneNumberSnake;
    const identifier = phoneNumber || email;

    return {
      id,
      label: identifier ? `${name} (${identifier})` : name,
      value: id,
      thumbnail: { name, src: thumbnail },
      ...rest,
      name,
      email,
      phoneNumber,
      icon: phoneNumber ? 'i-ri-whatsapp-fill' : undefined,
      action: 'contact',
      isContactCard: Boolean(phoneNumber),
      ...(phoneNumber
        ? {
            secondaryAction: {
              label: 'Abrir conversa',
              icon: 'i-lucide-message-circle',
            },
          }
        : {}),
    };
  });

  const typedPhoneNumber = searchValue.value.trim();
  const normalizedTypedPhone = normalizePhoneForComparison(typedPhoneNumber);
  const hasMatchingContact = contacts.some(
    contact =>
      normalizePhoneForComparison(contact.phoneNumber) === normalizedTypedPhone
  );

  if (isPhoneLikeInput(typedPhoneNumber) && !hasMatchingContact) {
    contacts.push({
      label: `WhatsApp (${typedPhoneNumber})`,
      value: typedPhoneNumber,
      name: typedPhoneNumber,
      phoneNumber: typedPhoneNumber,
      thumbnail: { name: typedPhoneNumber, src: '' },
      icon: 'i-ri-whatsapp-fill',
      action: 'create',
    });
  }

  return contacts;
});

const selectedContactLabel = computed(() => {
  const {
    name,
    email = '',
    phoneNumber = '',
    phone_number: phoneNumberSnake = '',
  } = props.selectedContact || {};
  const contactPhoneNumber = phoneNumber || phoneNumberSnake;
  if (contactPhoneNumber) return `${name} (${contactPhoneNumber})`;
  if (email) return `${name} (${email})`;
  return name || '';
});

const errorClass = computed(() => {
  return props.hasErrors
    ? '[&_input]:placeholder:!text-n-ruby-9 [&_input]:dark:placeholder:!text-n-ruby-9'
    : '';
});

const handleInput = value => {
  searchValue.value = value;
  const normalizedSearch = normalizePhoneSearchQuery(value);
  inputType.value =
    normalizedSearch !== value.trim() || isPhoneLikeInput(value)
      ? INPUT_TYPES.TEL
      : INPUT_TYPES.EMAIL;
  emit('searchContacts', normalizedSearch);
};
</script>

<template>
  <div class="relative flex-1 px-4 py-3 overflow-y-visible">
    <div class="flex items-center w-full gap-3 min-h-10">
      <label
        class="inline-flex items-center gap-1.5 text-sm font-medium text-n-slate-11 whitespace-nowrap"
      >
        <span
          v-if="
            inputType === INPUT_TYPES.TEL ||
            selectedContact?.phoneNumber ||
            selectedContact?.phone_number
          "
          class="i-ri-whatsapp-fill size-4 text-[#25D366]"
          aria-hidden="true"
        />
        <span>{{ t(`${i18nPrefix}.LABEL`) }}</span>
      </label>

      <div
        v-if="isCreatingContact"
        class="flex items-center gap-1.5 rounded-md bg-n-alpha-2 px-3 min-h-7 min-w-0"
      >
        <span class="text-sm truncate text-n-slate-12">
          {{ t(`${i18nPrefix}.CONTACT_CREATING`) }}
        </span>
      </div>
      <div
        v-else-if="selectedContact"
        class="flex items-center gap-1.5 rounded-md bg-n-alpha-2 min-h-7 min-w-0"
        :class="!contactId ? 'ltr:pl-3 rtl:pr-3 ltr:pr-1 rtl:pl-1' : 'px-3'"
      >
        <span class="text-sm truncate text-n-slate-12">
          {{
            isCreatingContact
              ? t(`${i18nPrefix}.CONTACT_CREATING`)
              : selectedContactLabel
          }}
        </span>
        <Button
          v-if="!contactId"
          variant="ghost"
          icon="i-lucide-x"
          color="slate"
          :disabled="contactId"
          size="xs"
          @click="emit('clearSelectedContact')"
        />
      </div>
      <TagInput
        v-else
        :placeholder="t(`${i18nPrefix}.TAG_INPUT_PLACEHOLDER`)"
        mode="single"
        :menu-items="contactsList"
        :show-dropdown="showContactsDropdown"
        :is-loading="isLoading"
        :disabled="contactableInboxesList?.length > 0 && showInboxesDropdown"
        allow-create
        :type="inputType"
        class="flex-1 min-h-10 [&_input]:!min-h-10 [&_input]:!text-base"
        :dropdown-class="[
          '!w-[40rem]',
          '!max-w-[calc(100vw-2rem)]',
          '!max-h-[calc(100vh-8rem)]',
        ]"
        :class="errorClass"
        focus-on-mount
        @input="handleInput"
        @on-click-outside="emit('updateDropdown', 'contacts', false)"
        @add="emit('setSelectedContact', $event)"
        @remove="emit('clearSelectedContact')"
        @secondary-action="emit('openConversation', $event)"
      >
        <template #menu-label="{ item }">
          <div
            v-if="item.isContactCard"
            class="flex min-w-0 flex-1 flex-col items-start gap-0.5 py-1 text-left"
            data-test="contact-card"
          >
            <span
              class="w-full whitespace-normal break-words text-sm font-medium text-n-slate-12"
            >
              {{ item.name }}
            </span>
            <span
              class="w-full whitespace-normal break-words text-xs text-n-slate-11"
            >
              {{ item.phoneNumber }}
            </span>
          </div>
          <span
            v-else
            class="min-w-0 text-sm font-420 truncate text-n-slate-12"
          >
            {{ item.label }}
          </span>
        </template>
        <template #menu-secondary-action="{ item }">
          <span
            class="i-lucide-message-circle size-4 shrink-0"
            aria-hidden="true"
          />
          <span class="truncate text-xs font-medium">
            {{ item.secondaryAction.label }}
          </span>
        </template>
      </TagInput>
    </div>
  </div>
</template>
